export type NotesBaseIconName = typeof NOTES_BASE_ICON_NAMES[number];

const supportedNotesBaseIconNames = new Set<string>(NOTES_BASE_ICON_NAMES);

class NotesBaseIconValue {
  readonly #name: NotesBaseIconName;

  constructor(name: NotesBaseIconName) {
    this.#name = name;
    Object.freeze(this);
  }

  name() {
    return this.#name;
  }
}

const notesBaseIconValues = new WeakSet<NotesBaseIconValue>();

function notesBaseIconValue(value: unknown) {
  return typeof value === "object" && value !== null && notesBaseIconValues.has(value as NotesBaseIconValue)
    ? value as NotesBaseIconValue
    : null;
}

/** Create an evaluator-owned icon value for a supported canonical Lucide name. */
export function createNotesBaseIconValue(name: string) {
  if (!supportedNotesBaseIconNames.has(name)) return null;
  const value = new NotesBaseIconValue(name as NotesBaseIconName);
  notesBaseIconValues.add(value);
  return value;
}

/** Return the canonical name only for evaluator-owned icon values. */
export function notesBaseIconName(value: unknown) {
  return notesBaseIconValue(value)?.name() ?? null;
}

